  function render(){if(!appHost)mount();if(!appHost)return;var lv=currentLevel();setText("#jlpt-eyebrow",tr("eyebrow"));setText("#jlpt-title",tr("title"));setText("#jlpt-intro-copy",tr("intro"));setText("#jlpt-target-label",tr("target"));setText("#jlpt-path-eyebrow",tr("levelPath"));setText("#jlpt-level-heading",tr("levelTitle"));setText("#jlpt-level-sub",tr("levelSub"));setText("#jlpt-four-week-title",tr("pathTitle2"));setText("#jlpt-four-week-sub",tr("pathSub"));setText("#jlpt-practice-title",tr("practiceTitle"));setText("#jlpt-practice-sub",tr("practiceSub"));setText("#jlpt-progress-title",tr("skillProgress"));setText("#jlpt-official-heading",tr("officialLinks"));setText("#jlpt-official-copy",tr("officialText"));setText("#jlpt-official-samples",tr("officialSamples"));setText("#jlpt-official-workbooks",tr("officialWorkbooks"));setText("#jlpt-score-guide",tr("scoreGuide"));setText("#jlpt-cando",tr("canDo"));setText("#jlpt-cando-listen",tr("canDoListen"));setText("#jlpt-dataset-note",tr("datasetNote"));var picker=$("#jlpt-level-picker");if(picker){picker.innerHTML=["N5","N4","N3","N2","N1"].map(function(code){return "<option value='"+code+"' "+(code===lv?"selected":"")+">"+code+" · "+esc(tr("level"+code))+"</option>"}).join("");picker.setAttribute("aria-label",tr("target"));picker.onchange=function(){selectLevel(picker.value)}}renderLevelCards(lv);renderCounts(lv);renderScore(lv);renderWeeks();renderN2Companion(lv);renderN2Resources(lv);renderSkills(lv);renderHistoryAndStats(lv);var practice=$("#jlpt-practice-host");if(practice){if(session){if(session.done)renderResult(practice);else if(session.atSectionBreak)renderSectionBreak(practice);else renderQuestion(practice)}else practice.innerHTML="<div class='jlpt-empty-state'><span>合</span><div><b>"+esc(currentLanguage()==="mn"?"Дасгалаа сонгоод эхлүүлээрэй.":currentLanguage()==="ja"?"分野を選んで練習を始めましょう。":"Choose a skill above to begin.")+"</b><p>"+esc(tr("scoreNote"))+"</p></div></div>"}}
  function shuffleQuestionLanguage(question,lang){if(question.source&&question.source.ask){var source=question.source;question.prompt=source.ask[lang]||source.ask.mn;question.choices=source.options[lang]||source.options.mn;question.correctValue=question.choices[question.correct];question.explanation=source.explain[lang]||source.explain.mn;question.translation=source.passage?source.passage.translation:source.translation||null}return question}
  function startPractice(skill,lv){var lang=currentLanguage(),questions=[];if(skill==="review")questions=buildReviewQuestions(lv,lang);else if(skill==="vocabulary"||skill==="kanji"||skill==="grammar"){if(!window.Phase2UI||!window.Phase2UI.startQuiz){alert(tr("unsupported"));return}window.Phase2UI.startQuiz({type:skill,mode:"mixed",count:10,level:lv});return}else if(skill==="reading")questions=sample(READING_BANK.filter(function(x){return x.level===lv}),READING_BANK.filter(function(x){return x.level===lv}).length).map(function(x){return questionFromBank(x,"reading",lang)});else if(skill==="listening")questions=sample(LISTENING_BANK.filter(function(x){return x.level===lv}),LISTENING_BANK.filter(function(x){return x.level===lv}).length).map(function(x){return questionFromBank(x,"listening",lang)});else if(skill==="mock")questions=buildMiniMock(lv,lang);else if(skill==="fullmock"){if(lv!=="N2"){alert(tr("unsupported"));return}var exam=buildN2FullMock(lang);if(!exam.questions.length){alert(tr("unsupported"));return}startSession(skill,lv,exam.questions,105*60,{sectionBreakIndex:exam.sectionBreakIndex,listeningSeconds:50*60});return}if(!questions.length){alert(tr("unsupported"));return}startSession(skill,lv,questions,skill==="mock"?(lv==="N2"?1500:720):0)}
  function startSession(skill,lv,questions,seconds,options){if(session&&!session.done){if(!window.confirm(tr("confirmQuit")))return;stopTimer();try{window.LearningStore.stopActivity()}catch{}}var activity=skill==="reading"?"reading":skill==="listening"?"listening":"quiz";try{window.LearningStore.startActivity(activity)}catch{}options=options||{};session={skill:skill,level:lv,questions:questions,index:0,correct:0,results:[],startedAt:Date.now(),remaining:Number(seconds)||0,done:false,answered:false,lang:currentLanguage(),timed:!!seconds,sectionBreakIndex:Number(options.sectionBreakIndex)||0,listeningSeconds:Number(options.listeningSeconds)||0,sectionTwo:false,atSectionBreak:false,fullElapsedSeconds:0};if(seconds)startTimer();if(location.hash!=="#jlpt")location.hash="#jlpt";render();var practiceHost=$("#jlpt-practice-host");if(practiceHost&&practiceHost.scrollIntoView)practiceHost.scrollIntoView({behavior:"smooth",block:"start"})}
  function startTimer(){stopTimer();timerHandle=window.setInterval(function(){if(!session||session.done)return;session.remaining=Math.max(0,session.remaining-1);var clock=$("#jlpt-timer");if(clock)clock.textContent=formatTime(session.remaining);if(session.remaining<=0)finishSession(true)},1000)}
