  function renderSectionBreak(host){var resultCount=session.results.filter(function(result,index){return index<session.sectionBreakIndex}).length,correct=session.results.filter(function(result,index){return index<session.sectionBreakIndex&&result.correct}).length;host.innerHTML="<article class='jlpt-section-transition'><span class='eyebrow'>JLPT N2 · "+esc(tr("fullSectionLanguageReading"))+" · 105:00</span><h3>"+esc(tr("fullBreakTitle"))+"</h3><p>"+esc(tr("fullBreakText"))+"</p>"+(session.sectionOneTimedOut?"<p class='jlpt-section-timeout'>"+esc(tr("timeUp"))+"</p>":"")+"<div class='jlpt-section-summary'><span>"+esc(tr("correct"))+" <b>"+correct+"</b></span><span>"+esc(tr("question"))+" <b>"+resultCount+" / "+session.sectionBreakIndex+"</b></span></div><div class='jlpt-section-break-actions'><button class='btn primary' type='button' id='jlpt-fullmock-continue'>"+esc(tr("fullBreakButton"))+" →</button><button class='btn quiet' type='button' id='jlpt-fullmock-quit'>× "+esc(tr("quit"))+"</button></div></article>";var button=$("#jlpt-fullmock-continue");if(button)button.onclick=continueFullMock;var quit=$("#jlpt-fullmock-quit");if(quit)quit.onclick=function(){if(window.confirm(tr("confirmQuit"))){stopTimer();try{window.LearningStore.stopActivity()}catch{}session=null;render()}}}
