  function answerQuestion(index){if(!session||session.done||session.answered)return;var q=session.questions[session.index];if(!q||!Number.isInteger(index)||index<0||index>=q.choices.length)return;session.answered=true;var ok=index===q.correct,selected=q.choices[index];if(ok)session.correct++;var result={id:q.id,skill:q.kind||q.type,correct:ok,selected:selected,expected:q.correctValue||q.choices[q.correct],prompt:q.prompt,jp:q.display||(q.passage&&q.passage.jp)||"",explanation:q.explanation||""};session.results.push(result);if(["vocabulary","kanji","grammar"].indexOf(q.type)>=0){try{window.LearningStore.recordAnswer(q.type,q.id,{correct:ok,selectedAnswer:selected,correctAnswer:result.expected,source:"jlpt-prep"})}catch{}}var buttons=document.querySelectorAll("[data-jlpt-choice]");Array.prototype.forEach.call(buttons,function(button){var choice=Number(button.dataset.jlptChoice);button.disabled=true;if(choice===q.correct)button.classList.add("is-correct");if(choice===index&&!ok)button.classList.add("is-wrong")});var fb=$("#jlpt-feedback");if(fb){var explanation=q.explanation||"";var translation=q.translation&&q.translation[session.lang];fb.innerHTML="<strong>"+(ok?"✓ "+esc(tr("correct")):"✕ "+esc(tr("incorrect"))+" · "+esc(result.expected))+"</strong><p>"+esc(explanation)+"</p>"+(translation?"<details class='jlpt-translation'><summary>"+esc(tr("detail"))+"</summary><p>"+esc(translation)+"</p></details>":"")};var next=$("#jlpt-next");if(next)next.disabled=false}
